import{_ as a,c as r,o,a3 as s}from"./chunks/framework.BusRvirq.js";const S=JSON.parse('{"title":"SyncShop: 엔터프라이즈 자주 묻는 질문 (FAQ)","description":"SyncShop의 Headless 연동, ERP/WMS 통합, 다이내믹 프라이싱 마진 보호 및 대규모 트래픽 오버셀 방지 관련 FAQ","frontmatter":{"title":"SyncShop: 엔터프라이즈 자주 묻는 질문 (FAQ)","sidebarTitle":"자주 묻는 질문","description":"SyncShop의 Headless 연동, ERP/WMS 통합, 다이내믹 프라이싱 마진 보호 및 대규모 트래픽 오버셀 방지 관련 FAQ","head":[["meta",{"name":"keywords","content":"SyncShop, FAQ, ERP 연동, WMS, 역마진 방지, 오버셀, Headless Commerce, 엔터프라이즈"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/syncshop/enterprise-faq.html"}]],"sort":6},"headers":[],"relativePath":"syncshop/enterprise-faq.md","filePath":"ko/syncshop/enterprise-faq.md","lastUpdated":1790216440000}'),l={name:"syncshop/enterprise-faq.md"};function n(i,e,t,c,d,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="엔터프라이즈-자주-묻는-질문-faq" tabindex="-1">엔터프라이즈 자주 묻는 질문 (FAQ) <a class="header-anchor" href="#엔터프라이즈-자주-묻는-질문-faq" aria-label="Permalink to “엔터프라이즈 자주 묻는 질문 (FAQ)”">​</a></h1><p>SyncShop 도입 및 운영 시 가장 많이 문의되는 기술 질문과 답변입니다.</p><hr><h3 id="q1-기존-사내-erp-또는-wms-물류창고관리-시스템과-어떻게-연동하나요" tabindex="-1">Q1. 기존 사내 ERP 또는 WMS(물류창고관리) 시스템과 어떻게 연동하나요? <a class="header-anchor" href="#q1-기존-사내-erp-또는-wms-물류창고관리-시스템과-어떻게-연동하나요" aria-label="Permalink to “Q1. 기존 사내 ERP 또는 WMS(물류창고관리) 시스템과 어떻게 연동하나요?”">​</a></h3><p><strong>A:</strong> SyncShop은 완전한 Headless API 기반 아키텍처로 구축되어 있습니다.</p><ul><li>표준 RESTful API 및 웹훅(Webhook)을 통해 SAP, 더존 등 기간계 ERP와 상품 마스터, 단가, 실재고 정보를 실시간 양방향 동기화할 수 있습니다.</li><li>물류 출고 및 운송장 번호 연동은 <code>sync-shop-admin</code>의 배치 스케줄러 또는 <code>manage_orders</code> MCP 도구를 통해 자동화됩니다.</li></ul><hr><h3 id="q2-다이내믹-프라이싱으로-가격을-일괄-변경할-때-역마진이-발생할-위험은-없나요" tabindex="-1">Q2. 다이내믹 프라이싱으로 가격을 일괄 변경할 때 역마진이 발생할 위험은 없나요? <a class="header-anchor" href="#q2-다이내믹-프라이싱으로-가격을-일괄-변경할-때-역마진이-발생할-위험은-없나요" aria-label="Permalink to “Q2. 다이내믹 프라이싱으로 가격을 일괄 변경할 때 역마진이 발생할 위험은 없나요?”">​</a></h3><p><strong>A:</strong> 다이내믹 프라이싱 실행 시 내부 <strong>Margin Safeguard Agent</strong>가 1차 방어선 역할을 수행합니다.</p><ul><li>상품별 마스터에 등록된 매입 원가(Cost Price)와 카테고리별 최소 보장 마진율(예: 15%)을 기준으로 실시간 시뮬레이션을 수행합니다.</li><li>단 1건이라도 원가 이하 판매 또는 마진율 위반이 발견되면 트랜잭션 실행이 즉시 차단되고 경고 리포트가 관제탑으로 전송됩니다.</li><li>작업 직전 원본 스냅샷이 자동 생성되므로 이상 발생 시 1초 이내에 직전 가격으로 원복(Rollback)할 수 있습니다.</li></ul><hr><h3 id="q3-타임세일이나-대규모-기획전-시-동시-접속으로-인한-초과-판매-overselling-를-어떻게-방지하나요" tabindex="-1">Q3. 타임세일이나 대규모 기획전 시 동시 접속으로 인한 초과 판매(Overselling)를 어떻게 방지하나요? <a class="header-anchor" href="#q3-타임세일이나-대규모-기획전-시-동시-접속으로-인한-초과-판매-overselling-를-어떻게-방지하나요" aria-label="Permalink to “Q3. 타임세일이나 대규모 기획전 시 동시 접속으로 인한 초과 판매(Overselling)를 어떻게 방지하나요?”">​</a></h3><p><strong>A:</strong> Redis 분산 락 및 원자적(Atomic) 연산을 결합한 2단계 재고 점유 구조를 채택하고 있습니다.</p><ul><li>고객이 주문서 생성 단계에 진입하는 순간 Redis의 원자적 <code>DECR</code> 연산으로 가용 재고를 선점(Lock)합니다.</li><li>결제가 최종 완료되면 RDBMS의 영속 재고를 차감하며, 지정된 결제 제한 시간(기본 15분) 내 미결제 시 선점 재고가 자동 반환됩니다.</li><li>이를 통해 수만 명의 동시 결제 요청 상황에서도 물리적 재고를 초과하는 결제 사고를 방지합니다.</li></ul><hr><h3 id="q4-온프레미스-폐쇄망-환경에서도-배포가-가능한가요" tabindex="-1">Q4. 온프레미스(폐쇄망) 환경에서도 배포가 가능한가요? <a class="header-anchor" href="#q4-온프레미스-폐쇄망-환경에서도-배포가-가능한가요" aria-label="Permalink to “Q4. 온프레미스(폐쇄망) 환경에서도 배포가 가능한가요?”">​</a></h3><p><strong>A:</strong> 가능합니다.</p><ul><li>SyncShop의 백엔드(<code>sync-shop-admin</code>), 에이전트 서버(<code>sync-shop-mcp-server</code>), 프론트엔드(<code>SyncShop Admin</code>)는 완전한 독립 컨테이너(Docker Compose / K8s Helm) 형태로 제공됩니다.</li><li>외부 클라우드 의존성 없이 사내 MariaDB/MySQL 및 사내 LLM 게이트웨이(SyncLLM)와 결합하여 폐쇄망에서도 자율 상거래 기능을 수행할 수 있습니다.</li></ul>',18)])])}const m=a(l,[["render",n]]);export{S as __pageData,m as default};
